(()=>{var t=document.querySelector("#status"),a=document.querySelector("#detail"),s=document.querySelector("#refresh");async function c(){t.textContent="checking\u2026",t.className="pill pill--pending";try{let e=await fetch("/api/health"),l=await e.json(),n=e.ok&&l.status==="healthy";t.textContent=n?"API healthy":`API returned ${e.status}`,t.className=`pill ${n?"pill--ok":"pill--fail"}`,a.textContent=JSON.stringify(l,null,2)}catch(e){t.textContent="API unreachable",t.className="pill pill--fail",a.textContent=String(e)}}s.addEventListener("click",c);c();})();
